package com.jesuskrastev.bali.domain.path

/**
 * Static question bank for every lesson node in the DGT learning path.
 * Keys match deterministic node IDs from DgtLearningPathTemplate.
 */
object LessonQuestionBank {

    /**
     * Base download URL for DGT traffic sign images hosted in Firebase Storage
     * (public-read, `signs/` path). Images were re-hosted from Wikimedia Commons
     * because Coil's requests to commons.wikimedia.org were being rate-limited
     * (HTTP 429) without an identifying User-Agent, causing signs to fail to load.
     */
    private const val SIGN_IMAGE_BASE_URL =
        "https://firebasestorage.googleapis.com/v0/b/bali-ai-facc4.firebasestorage.app/o/signs%2F"

    /** Builds the public Firebase Storage download URL for a sign image PNG by file name (without extension). */
    fun signImage(fileName: String) = "${SIGN_IMAGE_BASE_URL}$fileName.png?alt=media"

    /** Builds the public Firebase Storage URL for a mini-game asset stored under `game-assets/`. */
    fun gameAsset(fileName: String) =
        "https://firebasestorage.googleapis.com/v0/b/bali-ai-facc4.firebasestorage.app/o/game-assets%2F$fileName.png?alt=media"

    data class StaticQuestion(
        val text: String,
        val options: List<String>,
        val correctAnswerIndex: Int,
        val explanation: String,
        val imageUrl: String? = null
    )

    private val questionsPerNode: Map<String, List<StaticQuestion>> = mapOf(

        // ══════════════════════════════════════════════════════════════════
        // SECCIÓN 0 — El Conductor
        // ══════════════════════════════════════════════════════════════════

        "node_0_0_lesson" to listOf( // Factores físicos y psíquicos
            StaticQuestion("¿Qué factor psicológico puede afectar más negativamente a la conducción?", listOf("El exceso de confianza", "La experiencia al volante", "El conocimiento de la ruta"), 0, "El exceso de confianza reduce la percepción del riesgo y aumenta las probabilidades de accidente."),
            StaticQuestion("¿Cómo afecta el estrés a la conducción?", listOf("No tiene ningún efecto", "Mejora la atención del conductor", "Aumenta la agresividad y reduce la concentración"), 2, "El estrés provoca reacciones más impulsivas, falta de atención y conducción agresiva."),
            StaticQuestion("¿Cuánto tarda el organismo en alcanzar la máxima capacidad visual al pasar de una zona iluminada a una oscura?", listOf("Unos 2 segundos", "Unos 15-30 segundos", "Más de 5 minutos"), 1, "La adaptación a la oscuridad requiere entre 15 y 30 segundos."),
            StaticQuestion("Las emociones intensas como la ira o la euforia, ¿afectan a la conducción?", listOf("No, solo el alcohol afecta", "Sí, alteran la toma de decisiones y la percepción del riesgo", "Solo afectan a conductores noveles"), 1, "Cualquier emoción intensa distrae y altera la capacidad de juicio al volante."),
            StaticQuestion("¿Qué debe hacer un conductor que se siente indispuesto?", listOf("Conducir más despacio", "Detenerse en un lugar seguro", "Abrir las ventanillas y seguir"), 1, "Lo correcto es detenerse en un lugar seguro hasta encontrarse bien."),
            StaticQuestion("¿Qué ocurre con el campo visual a medida que aumenta la velocidad?", listOf("Se reduce, aumentando el efecto de visión túnel", "Se amplía, viendo más carretera", "No varía con la velocidad"), 0, "A mayor velocidad, el campo visual periférico se estrecha, dificultando detectar peligros laterales."),
            StaticQuestion("¿Cuál es el tiempo medio de reacción de un conductor en condiciones normales?", listOf("Aproximadamente 1 segundo", "Unos 5 segundos", "Menos de 0,1 segundos"), 0, "El tiempo de reacción medio ronda 1 segundo, y aumenta con la fatiga, el alcohol o las distracciones."),
            StaticQuestion("¿Cómo afecta la edad avanzada a la conducción?", listOf("No afecta en ningún caso", "Puede reducir reflejos y campo visual, aunque la experiencia compensa parte del riesgo", "Mejora siempre los reflejos"), 1, "Con la edad pueden disminuir reflejos y visión, pero la experiencia acumulada ayuda a anticipar riesgos."),
            StaticQuestion("¿Qué es la percepción del riesgo al volante?", listOf("La velocidad máxima permitida en la vía", "La capacidad de anticipar situaciones peligrosas antes de que ocurran", "El tiempo de frenado del vehículo"), 1, "La percepción del riesgo es la habilidad de detectar y anticipar peligros antes de que se materialicen."),
            StaticQuestion("¿Puede la pérdida de audición afectar a la conducción?", listOf("No, la conducción es una tarea únicamente visual", "Sí, dificulta detectar sirenas, cláxones u otros avisos sonoros", "Solo afecta en vías urbanas"), 1, "La audición ayuda a detectar vehículos de emergencia y avisos sonoros de peligro.")
        ),

        "node_0_1_lesson" to listOf( // Alcohol
            StaticQuestion("¿Cuál es la tasa máxima de alcohol en sangre para conductores en general?", listOf("0,5 g/l", "0,8 g/l", "0,3 g/l"), 0, "El límite general es 0,5 g/l en sangre (0,25 mg/l en aire espirado)."),
            StaticQuestion("¿Cuál es la tasa máxima de alcohol para conductores noveles?", listOf("0,5 g/l", "0,3 g/l", "0,1 g/l"), 1, "Los conductores noveles y profesionales tienen un límite de 0,3 g/l en sangre."),
            StaticQuestion("¿Qué efectos produce el alcohol en la conducción?", listOf("Mejora los reflejos", "Aumenta el campo visual", "Disminuye los reflejos y la concentración"), 2, "El alcohol deteriora reflejos, coordinación, concentración y percepción de distancias."),
            StaticQuestion("¿Se puede rechazar una prueba de alcoholemia?", listOf("Sí, sin consecuencias", "No, negarse es delito penal", "Solo si no ha bebido"), 1, "Negarse a realizar la prueba de alcoholemia es un delito tipificado en el Código Penal."),
            StaticQuestion("¿Cuándo alcanza el alcohol su máxima concentración en sangre?", listOf("A los 5 minutos de ingerirlo", "Entre 30 y 90 minutos después", "A las 3 horas"), 1, "El pico de alcoholemia se alcanza entre 30 y 90 minutos tras la ingesta."),
            StaticQuestion("¿El café o una ducha fría aceleran la eliminación del alcohol del organismo?", listOf("Sí, el café acelera el metabolismo del alcohol", "No, solo el paso del tiempo elimina el alcohol de la sangre", "Sí, pero solo la ducha fría"), 1, "Ningún remedio casero acelera la eliminación del alcohol; solo el tiempo reduce la tasa de alcoholemia."),
            StaticQuestion("¿A partir de qué tasa de alcohol en sangre se considera delito contra la seguridad vial?", listOf("0,5 g/l en sangre", "1,2 g/l en sangre o 0,60 mg/l en aire espirado", "0,3 g/l en sangre"), 1, "Superar 1,2 g/l en sangre (0,60 mg/l en aire) constituye delito, no solo infracción administrativa."),
            StaticQuestion("¿Cómo afecta el alcohol al tiempo de reacción?", listOf("Lo reduce", "No lo afecta", "Lo aumenta considerablemente"), 2, "El alcohol ralentiza los reflejos y aumenta el tiempo necesario para reaccionar ante un imprevisto."),
            StaticQuestion("Si varias personas se turnan para conducir en un viaje largo, ¿quién debe respetar el límite de alcohol?", listOf("Solo el conductor que inició el trayecto", "Todas las personas que vayan a conducir en algún momento", "Solo si hay un control policial"), 1, "El límite de alcoholemia debe cumplirlo cualquier persona que vaya a ponerse al volante, sin excepción."),
            StaticQuestion("¿A qué ritmo aproximado elimina el organismo el alcohol de la sangre?", listOf("Todo en 15 minutos", "Unos 0,15 g/l por hora", "Solo se elimina durmiendo"), 1, "El cuerpo metaboliza el alcohol a un ritmo aproximado de 0,15 g/l por hora, sin poder acelerarse.")
        ),

        "node_0_2_lesson" to listOf( // Drogas y medicamentos
            StaticQuestion("¿Cómo afectan las drogas estimulantes (cocaína, anfetaminas) a la conducción?", listOf("Mejoran la capacidad de reacción", "Provocan falsa seguridad y agresividad", "No afectan si se toman en pequeñas dosis"), 1, "Los estimulantes dan falsa sensación de control y provocan conducción agresiva."),
            StaticQuestion("¿Qué medicamentos pueden afectar a la conducción?", listOf("Solo los psicofármacos", "Solo los que llevan pictograma en el envase", "Ansiolíticos, antihistamínicos, analgésicos y otros"), 2, "Muchos medicamentos comunes pueden causar somnolencia, mareos o reducción de reflejos."),
            StaticQuestion("Si un medicamento lleva un triángulo rojo con un coche en el envase, ¿qué significa?", listOf("Que no se puede conducir bajo ningún concepto", "Que puede afectar a la capacidad de conducción", "Que solo afecta a conductores profesionales"), 1, "El pictograma advierte de que el medicamento puede afectar a la conducción."),
            StaticQuestion("¿Es delito conducir bajo los efectos de drogas?", listOf("No, solo es infracción administrativa", "Sí, puede ser delito contra la seguridad vial", "Solo si se provoca un accidente"), 1, "Conducir bajo la influencia de drogas es delito contra la seguridad vial."),
            StaticQuestion("¿El cannabis afecta a la conducción?", listOf("No, es una droga suave", "Sí, altera la percepción del tiempo y reduce los reflejos", "Solo si se fuma mientras se conduce"), 1, "El cannabis altera la percepción espacio-temporal y reduce la capacidad de reacción."),
            StaticQuestion("¿Qué tipo de prueba se utiliza habitualmente en un control de carretera para detectar drogas?", listOf("Un análisis de sangre obligatorio en el momento", "Un test de saliva", "Solo una prueba visual del agente"), 1, "Los controles de drogas en carretera se realizan mediante un test de saliva."),
            StaticQuestion("¿Qué ocurre si se combinan alcohol y drogas antes de conducir?", listOf("Los efectos negativos se potencian entre sí", "Se anulan mutuamente", "No hay ningún riesgo adicional"), 0, "La combinación de alcohol y drogas multiplica el deterioro de reflejos y capacidad de juicio."),
            StaticQuestion("¿Se puede rechazar la prueba de detección de drogas en un control?", listOf("Sí, es voluntaria", "No, negarse es delito igual que con el alcohol", "Solo pueden negarse los conductores noveles"), 1, "Negarse a la prueba de drogas es delito, con el mismo tratamiento legal que negarse a la de alcoholemia."),
            StaticQuestion("¿Cómo afectan los ansiolíticos a la conducción?", listOf("Mejoran la concentración", "Pueden causar somnolencia y reducir los reflejos", "No tienen ningún efecto si se toman por la noche"), 1, "Los ansiolíticos son depresores del sistema nervioso y pueden provocar somnolencia y lentitud de reflejos."),
            StaticQuestion("¿Es seguro conducir tras tomar un medicamento nuevo sin conocer aún sus efectos?", listOf("Sí, siempre es seguro", "No, se recomienda esperar a conocer cómo afecta antes de conducir", "Solo es peligroso en autopistas"), 1, "Antes de conducir tras iniciar un tratamiento nuevo conviene comprobar cómo afecta individualmente.")
        ),

        "node_0_3_lesson" to listOf( // Fatiga y somnolencia
            StaticQuestion("¿Cada cuánto tiempo se recomienda descansar en viajes largos?", listOf("Cada 3-4 horas", "Cada 2 horas o 200 km", "Cada hora"), 1, "Se recomienda descansar al menos 15-20 minutos cada 2 horas o 200 km."),
            StaticQuestion("¿Cuál es el síntoma más peligroso de la fatiga?", listOf("Bostezar frecuentemente", "Los microsueños", "Cambiar de postura"), 1, "Los microsueños son pérdidas de consciencia de 2-3 segundos sin que el conductor lo perciba."),
            StaticQuestion("¿A qué horas del día es más frecuente la somnolencia al volante?", listOf("A mediodía", "De 3 a 5 de la madrugada y de 14 a 16 horas", "Al anochecer"), 1, "Los ritmos circadianos provocan mayor somnolencia entre las 3-5h y las 14-16h."),
            StaticQuestion("¿Qué debe hacer si siente sueño al volante?", listOf("Poner música alta y abrir ventanillas", "Detenerse y dormir una siesta corta de 20 minutos", "Beber un café y seguir conduciendo"), 1, "Lo más eficaz es detenerse y dormir 20 minutos; café + siesta es la mejor combinación."),
            StaticQuestion("Una comida copiosa antes de conducir, ¿afecta a la conducción?", listOf("No, da energía", "Sí, favorece la somnolencia postprandial", "Solo si contiene alcohol"), 1, "La digestión pesada desvía sangre al aparato digestivo, causando somnolencia."),
            StaticQuestion("¿Cuáles son señales de aviso de que se aproxima la fatiga al volante?", listOf("Aumento del apetito", "Bostezos frecuentes, pesadez de párpados y dificultad para concentrarse", "Mejora de los reflejos"), 1, "Bostezar, sentir pesadez en los párpados y perder concentración son avisos claros de fatiga."),
            StaticQuestion("¿Puede la fatiga tener efectos similares a los del alcohol en la conducción?", listOf("No, son fenómenos completamente distintos", "Sí, reduce reflejos y capacidad de reacción de forma parecida", "Solo afecta a la vista"), 1, "La fatiga extrema deteriora reflejos y atención de forma comparable a ciertos niveles de alcoholemia."),
            StaticQuestion("¿Ventilar el vehículo o poner música alta elimina la fatiga?", listOf("Sí, elimina completamente el cansancio", "No, solo enmascara temporalmente los síntomas", "Sí, si se hace durante más de una hora"), 1, "Estos remedios solo disimulan momentáneamente el cansancio; no sustituyen al descanso real."),
            StaticQuestion("¿Qué franja horaria nocturna incrementa especialmente el riesgo de sueño al volante?", listOf("Entre las 18:00 y las 20:00", "Entre las 00:00 y las 06:00", "Entre las 10:00 y las 12:00"), 1, "El ritmo circadiano provoca máxima somnolencia durante la madrugada, entre las 00:00 y las 06:00."),
            StaticQuestion("¿Es recomendable planificar el viaje antes de salir para evitar la fatiga?", listOf("No es necesario planificar nada", "Sí, incluyendo paradas regulares en el itinerario", "Solo en viajes de más de 1.000 km"), 1, "Planificar paradas periódicas de antemano ayuda a prevenir la fatiga acumulada en trayectos largos.")
        ),

        "node_0_4_lesson" to listOf( // Distracciones
            StaticQuestion("¿Cuál es la principal causa de accidentes de tráfico?", listOf("El exceso de velocidad", "Las distracciones", "El mal estado de la vía"), 1, "Las distracciones al volante son la primera causa de siniestralidad vial."),
            StaticQuestion("¿Está permitido manipular el GPS mientras se conduce?", listOf("Sí, siempre que sea manos libres", "No, debe programarse antes de iniciar la marcha", "Sí, si se hace con una sola mano"), 1, "El GPS debe programarse con el vehículo detenido para evitar distracciones."),
            StaticQuestion("¿Cuántos metros recorre a ciegas un conductor que mira el móvil 2 segundos a 120 km/h?", listOf("Unos 33 metros", "Unos 67 metros", "Unos 15 metros"), 1, "A 120 km/h se recorren 33 m/s, por lo que en 2 segundos son unos 67 metros sin mirar."),
            StaticQuestion("¿Usar auriculares mientras se conduce está permitido?", listOf("Sí, si se usa solo uno", "No, está prohibido", "Sí, siempre"), 1, "Está prohibido usar auriculares o cascos conectados a dispositivos de sonido mientras se conduce."),
            StaticQuestion("¿Qué tipo de distracción es hablar con los pasajeros?", listOf("Distracción visual", "Distracción cognitiva y auditiva", "No es una distracción"), 1, "Hablar distrae la mente (cognitiva) y el oído (auditiva) del tráfico."),
            StaticQuestion("¿Está permitido sujetar el teléfono móvil con la mano mientras se conduce, aunque sea para hablar?", listOf("Sí, si la llamada dura menos de un minuto", "No, está prohibido sujetar o manipular el móvil en cualquier circunstancia", "Sí, siempre que se use una sola mano"), 1, "Sujetar o manipular el móvil mientras se conduce está prohibido, sea cual sea el uso que se le dé."),
            StaticQuestion("¿Qué sanción conlleva el uso del móvil sin manos libres mientras se conduce?", listOf("Solo una advertencia verbal", "Multa económica y pérdida de puntos del carné", "Ninguna si no hay accidente"), 1, "Usar el móvil sin manos libres al volante es infracción grave con multa y pérdida de puntos."),
            StaticQuestion("¿Llevar una mascota suelta dentro del vehículo es una distracción sancionable?", listOf("No, las mascotas pueden ir libremente", "Sí, las mascotas deben ir sujetas o en un habitáculo adecuado", "Solo se sanciona en autopistas"), 1, "Las mascotas deben viajar sujetas o en transportín para no distraer ni poner en riesgo al conductor."),
            StaticQuestion("¿Comer mientras se conduce está expresamente prohibido por la normativa?", listOf("Está totalmente prohibido en cualquier circunstancia", "No está expresamente prohibido, pero es sancionable si reduce la atención necesaria", "Solo está prohibido en vías urbanas"), 1, "No hay una prohibición específica de comer, pero sí de conducir sin la atención permanente que exige la vía."),
            StaticQuestion("¿Qué tipo de distracción provoca mirar carteles publicitarios llamativos junto a la vía?", listOf("No se considera una distracción", "Distracción visual y cognitiva", "Solo distracción auditiva"), 1, "Desviar la vista y la atención hacia un cartel publicitario distrae tanto visual como mentalmente.")
        ),

        "node_0_5_lesson" to listOf( // Cinturón, airbag y cabecero
            StaticQuestion("¿Es obligatorio el uso del cinturón de seguridad en vías urbanas?", listOf("No, solo en vías interurbanas", "Sí, en todas las vías", "Solo en autopistas y autovías"), 1, "El cinturón es obligatorio en todas las vías, tanto urbanas como interurbanas."),
            StaticQuestion("¿El airbag sustituye al cinturón de seguridad?", listOf("Sí, si el coche lo lleva no hace falta cinturón", "No, el airbag es un complemento del cinturón", "Solo en trayectos urbanos"), 1, "El airbag está diseñado para funcionar junto al cinturón; sin él puede causar lesiones."),
            StaticQuestion("¿Para qué sirve el reposacabezas?", listOf("Para mayor comodidad", "Para evitar el latigazo cervical en colisiones traseras", "Para apoyar la cabeza y dormir"), 1, "El reposacabezas previene el latigazo cervical en caso de impacto por detrás."),
            StaticQuestion("¿Cómo debe colocarse correctamente el cinturón?", listOf("La banda diagonal sobre el hombro y la horizontal sobre las caderas", "Lo más holgado posible", "La banda diagonal bajo el brazo"), 0, "La banda superior va sobre el hombro y la inferior sobre los huesos de la cadera, ajustado al cuerpo."),
            StaticQuestion("¿Qué personas pueden estar exentas del uso del cinturón?", listOf("Los mayores de 65 años", "Personas con certificado médico de exención", "Los conductores profesionales"), 1, "Solo se exime a personas con certificado médico oficial de exención."),
            StaticQuestion("¿Deben las mujeres embarazadas usar el cinturón de seguridad?", listOf("No, están exentas automáticamente", "Sí, colocando la banda inferior lo más baja posible, bajo el abdomen", "Solo el cinturón diagonal, sin la banda inferior"), 1, "El cinturón es obligatorio también en el embarazo, ajustando la banda inferior bajo el abdomen."),
            StaticQuestion("¿Qué sanción tiene circular sin el cinturón de seguridad abrochado?", listOf("Solo una advertencia", "Multa económica y pérdida de puntos del carné", "No tiene sanción si es un trayecto corto"), 1, "No usar el cinturón es infracción grave, con multa y pérdida de puntos, sea cual sea la duración del trayecto."),
            StaticQuestion("¿Para qué sirve el airbag lateral?", listOf("Para sustituir al cinturón de seguridad", "Para proteger tórax y cabeza en impactos laterales", "Para inflar los reposacabezas"), 1, "El airbag lateral protege tórax y cabeza en colisiones por el costado del vehículo."),
            StaticQuestion("¿Qué distancia mínima se recomienda entre el pecho del conductor y el volante por seguridad del airbag?", listOf("Menos de 10 cm", "Unos 25 cm", "No influye la distancia"), 1, "Se recomienda mantener unos 25 cm entre el pecho y el volante para que el airbag actúe con seguridad."),
            StaticQuestion("A partir de los 135 cm de estatura, ¿puede un menor usar solo el cinturón de seguridad sin SRI?", listOf("No, hasta los 18 años siempre necesita SRI", "Sí, ya no es obligatorio el SRI, aunque se recomienda seguir usándolo más tiempo", "Solo si pesa menos de 20 kg"), 1, "A partir de 135 cm deja de ser obligatorio el SRI, aunque se recomienda prolongar su uso mientras sea posible.")
        ),

        "node_0_6_lesson" to listOf( // SRI
            StaticQuestion("¿Hasta qué altura es obligatorio usar un sistema de retención infantil (SRI)?", listOf("Hasta los 12 años", "Hasta 135 cm de estatura", "Hasta los 10 años"), 1, "Los menores de 135 cm deben ir en un SRI homologado adecuado a su talla y peso."),
            StaticQuestion("¿Pueden los niños viajar en el asiento delantero?", listOf("Nunca", "Sí, con SRI si el vehículo no tiene asientos traseros o están ocupados por otros menores", "Sí, siempre que lleven cinturón"), 1, "Excepcionalmente pueden ir delante con SRI si no hay plazas traseras disponibles."),
            StaticQuestion("¿Qué grupo de SRI es adecuado para un bebé recién nacido?", listOf("Grupo 0 o 0+, a contramarcha", "Grupo 2, mirando hacia delante", "Un cojín elevador"), 0, "Los recién nacidos deben ir en el grupo 0/0+ en posición a contramarcha."),
            StaticQuestion("¿Está permitido llevar a un niño en brazos en el coche?", listOf("Sí, en el asiento trasero", "No, nunca", "Sí, si va con cinturón el adulto"), 1, "Llevar a un niño en brazos está prohibido; en caso de colisión es imposible retenerlo."),
            StaticQuestion("¿Cada cuánto hay que revisar el SRI?", listOf("Cada año en la ITV", "Regularmente y sustituir tras un accidente", "No necesita revisión"), 1, "El SRI debe revisarse periódicamente y sustituirse tras cualquier accidente, aunque parezca en buen estado."),
            StaticQuestion("¿Qué ventaja ofrece el sistema de anclaje ISOFIX en los SRI?", listOf("Permite prescindir del cinturón del vehículo siempre", "Una instalación más rápida, sencilla y segura que con el cinturón", "Solo sirve para bebés menores de 6 meses"), 1, "ISOFIX fija el SRI directamente a la carrocería, reduciendo el riesgo de una instalación incorrecta."),
            StaticQuestion("¿Hasta qué edad se recomienda mantener a los niños a contramarcha en el SRI?", listOf("Solo hasta los 6 meses", "Lo más tarde posible, orientativamente al menos hasta los 4 años", "Nunca, deben ir mirando hacia delante desde el nacimiento"), 1, "Los expertos recomiendan mantener a contramarcha el mayor tiempo posible, al menos hasta los 4 años."),
            StaticQuestion("¿Es recomendable comprar un SRI de segunda mano sin conocer su historial?", listOf("Sí, siempre es igual de seguro", "No, podría tener daños estructurales no visibles", "Solo si tiene menos de un año"), 1, "Un SRI de origen desconocido puede haber sufrido un impacto que comprometa su seguridad sin que se note."),
            StaticQuestion("¿Qué sanción puede conllevar llevar a un menor sin el SRI adecuado?", listOf("Ninguna sanción si el trayecto es urbano", "Multa y pérdida de puntos para el conductor", "Solo una advertencia la primera vez"), 1, "No usar el SRI homologado y adecuado es infracción grave para el conductor del vehículo."),
            StaticQuestion("¿Qué significa que un SRI esté homologado como i-Size?", listOf("Que solo puede usarse en coches nuevos", "Que cumple una normativa europea basada en la altura del niño, no solo en el peso", "Que es válido únicamente para bebés prematuros"), 1, "La normativa i-Size clasifica los SRI según la altura del menor, además de mejorar la protección lateral.")
        ),

        // ══════════════════════════════════════════════════════════════════
        // SECCIÓN 1 — El Vehículo
        // ══════════════════════════════════════════════════════════════════

        "node_1_0_lesson" to listOf( // Documentación obligatoria
            StaticQuestion("¿Qué documentos debe llevar siempre el conductor?", listOf("DNI y seguro", "Permiso de conducción, seguro en vigor y documentación del vehículo", "Solo el permiso de conducción"), 1, "Se debe llevar permiso de conducir, permiso de circulación, tarjeta ITV y recibo del seguro."),
            StaticQuestion("¿Es obligatorio llevar el permiso de conducción en formato físico?", listOf("Sí, siempre", "No, la DGT puede comprobar su validez electrónicamente", "Solo en viajes internacionales"), 1, "La DGT dispone de una base de datos electrónica; no obstante, es recomendable llevarlo."),
            StaticQuestion("¿Qué ocurre si circula sin seguro obligatorio?", listOf("Una multa leve", "Sanción económica grave y posible inmovilización", "No pasa nada si no hay accidente"), 1, "Circular sin seguro es infracción muy grave con multas de 601 a 3.005 euros."),
            StaticQuestion("¿Quién debe llevar el permiso de circulación del vehículo?", listOf("Solo el propietario", "El conductor que circule con el vehículo", "Solo en viajes interurbanos"), 1, "Quien conduce el vehículo debe poder acreditar la documentación del mismo."),
            StaticQuestion("¿La tarjeta ITV es obligatoria?", listOf("No, es solo informativa", "Sí, acredita que el vehículo ha pasado la inspección", "Solo para vehículos de más de 10 años"), 1, "La tarjeta ITV es obligatoria y certifica que el vehículo está en condiciones aptas."),
