            StaticQuestion("¿Qué hace el sistema de reconocimiento de señales de tráfico?", listOf("Sustituye la necesidad de mirar las señales", "Detecta señales como límites de velocidad y los muestra en el cuadro de mandos", "Solo funciona en autopistas"), 1, "Este asistente identifica señales de tráfico y las muestra en el cuadro para apoyar al conductor.")
        ),

        "node_1_7_lesson" to listOf( // Mantenimiento e ITV
