            StaticQuestion("¿Qué forma tienen las señales de peligro?", listOf("Circular con borde rojo", "Triangular con borde rojo y vértice hacia arriba", "Cuadrada con fondo azul"), 1, "Las señales de peligro son triángulos con borde rojo y fondo blanco."),
            StaticQuestion("¿Qué indica esta señal triangular con un semáforo?", listOf("Que hay un semáforo próximo", "Que el semáforo está averiado", "Que hay un paso de peatones"), 0, "La señal P-3 advierte de la proximidad de un semáforo.", signImage("p3")),
            StaticQuestion("¿A qué distancia suelen colocarse las señales de peligro?", listOf("Justo en el punto de peligro", "Entre 150 y 250 metros antes", "A 500 metros"), 1, "En vías interurbanas se colocan entre 150 y 250 metros antes del peligro."),
            StaticQuestion("¿Qué advierte esta señal con peatones?", listOf("Zona escolar", "Proximidad de un paso de peatones", "Calle peatonal"), 1, "La señal P-20a advierte de la proximidad de un paso de peatones.", signImage("p20a")),
            StaticQuestion("¿Qué indica una señal de peligro que muestra una curva pronunciada?", listOf("Que la vía termina", "Que se aproxima una curva cerrada y debe reducirse la velocidad", "Que hay un cruce con prioridad"), 1, "Esta señal advierte de una curva pronunciada próxima, avisando para reducir la velocidad con antelación."),
