            StaticQuestion("¿Qué indica la señal circular roja con rectángulo blanco horizontal?", listOf("Prohibido estacionar", "Dirección prohibida (sentido contrario)", "Vía cortada"), 1, "La señal R-101 prohíbe la entrada porque indica dirección prohibida.", signImage("r101")),
