        "node_6_0_lesson" to listOf( // Tipos de vía
            StaticQuestion("¿Cuál es la velocidad máxima en autopistas?", listOf("100 km/h", "120 km/h", "130 km/h"), 1, "El límite máximo para turismos en autopistas es 120 km/h."),
            StaticQuestion("¿Qué diferencia hay entre autopista y autovía?", listOf("La autopista siempre es de peaje", "La autopista no tiene cruces a nivel; la autovía puede tenerlos excepcionalmente", "No hay diferencia"), 1, "Las autopistas no tienen cruces a nivel ni accesos directos; las autovías pueden tener algún acceso."),
            StaticQuestion("¿Qué es una travesía?", listOf("Un tramo de autopista en obras", "Un tramo de carretera que discurre por dentro de una población", "Una rotonda"), 1, "Una travesía es el tramo de una carretera que pasa por el interior de un núcleo urbano."),
            StaticQuestion("¿Qué velocidad máxima rige en una vía convencional de dos carriles?", listOf("100 km/h", "90 km/h", "80 km/h"), 1, "En carreteras convencionales con un carril por sentido el límite es 90 km/h."),
            StaticQuestion("¿Los caminos rurales tienen límite de velocidad?", listOf("No, son libres", "Sí, la prudencia lo exige y normalmente es 30-50 km/h", "Solo si están señalizados"), 1, "Los caminos rurales están sometidos a las normas generales; la prudencia manda."),
            StaticQuestion("¿Qué es el arcén?", listOf("Un carril adicional para adelantar", "Franja lateral de la calzada no destinada a la circulación normal de vehículos", "Un tipo de rotonda"), 1, "El arcén es la franja lateral, pavimentada o no, situada al borde de la calzada, no destinada a la circulación de vehículos."),
            StaticQuestion("¿Qué es la berma?", listOf("Zona ajardinada de una rotonda", "Franja de terreno entre la calzada o el arcén y la cuneta o el talud, generalmente no pavimentada", "El carril central de una autovía"), 1, "La berma es la franja de terreno comprendida entre la calzada o el arcén y la cuneta o el talud."),
            StaticQuestion("¿Qué es una vía de servicio?", listOf("Un carril para vehículos de emergencia", "Vía adyacente y paralela a la principal, para acceso a fincas o poblaciones colindantes", "Un carril reservado a autobuses"), 1, "Las vías de servicio son calzadas paralelas a las vías principales destinadas a accesos y al tráfico local."),
            StaticQuestion("¿Qué es la calzada?", listOf("Toda la superficie de la vía, incluidos arcenes", "Parte de la vía destinada a la circulación de vehículos", "Solo el carril de adelantamiento"), 1, "La calzada es la zona de la vía destinada a la circulación de vehículos; no incluye arcenes ni aceras."),
            StaticQuestion("¿Cómo se llama la zona que separa dos calzadas de sentido contrario?", listOf("Mediana", "Berma", "Arcén"), 0, "La mediana es la zona longitudinal que separa dos calzadas de sentidos opuestos.")
        ),

        "node_6_1_lesson" to listOf( // Condiciones meteorológicas adversas
            StaticQuestion("¿Cómo afecta la lluvia a la conducción?", listOf("No afecta con buenos neumáticos", "Reduce la adherencia y la visibilidad", "Solo afecta la visibilidad"), 1, "La lluvia reduce la adherencia del asfalto y la visibilidad del conductor."),
            StaticQuestion("¿Qué es lo primero que debe hacer si hay niebla?", listOf("Poner luces largas", "Reducir velocidad y encender la luz de niebla delantera/trasera", "Detenerse inmediatamente"), 1, "Con niebla se reduce velocidad y se enciende la luz antiniebla delantera; la trasera, solo con niebla densa."),
            StaticQuestion("¿Con viento lateral fuerte, ¿qué vehículos son más vulnerables?", listOf("Los coches bajos", "Furgonetas, camiones y vehículos con gran superficie lateral", "Las motos"), 1, "Los vehículos con gran superficie lateral (furgonetas, camiones) son muy vulnerables al viento lateral."),
            StaticQuestion("¿Qué debe hacer si encuentra hielo en la calzada?", listOf("Frenar bruscamente", "Reducir velocidad suavemente y evitar maniobras bruscas", "Acelerar para pasar rápido"), 1, "En hielo se debe reducir velocidad de forma progresiva y evitar frenazos y volantazos."),
            StaticQuestion("¿Las luces antiniebla traseras se pueden usar siempre que llueve?", listOf("Sí, siempre", "No, solo con niebla densa, lluvia muy intensa o nubes de polvo", "Solo de noche"), 1, "Las antiniebla traseras solo se usan con visibilidad gravemente reducida; deslumbran si no."),
            StaticQuestion("¿Qué se recomienda hacer con la distancia de seguridad cuando llueve?", listOf("No hace falta aumentarla", "Aumentarla, ya que la distancia de frenado puede duplicarse", "Reducirla"), 1, "Con lluvia la adherencia baja y la distancia de frenado aumenta considerablemente; conviene aumentar la distancia de seguridad."),
            StaticQuestion("¿Qué es el aquaplaning o hidroplaneo?", listOf("Pérdida de adherencia por acumulación de agua entre el neumático y el asfalto", "Un tipo de frenada de emergencia", "Un sistema de seguridad del vehículo"), 0, "El aquaplaning ocurre cuando una capa de agua impide el contacto directo entre el neumático y la calzada."),
            StaticQuestion("¿Qué se debe hacer si el vehículo empieza a aquaplanear?", listOf("Frenar bruscamente y girar el volante", "Soltar el acelerador con suavidad, sin frenar bruscamente ni girar el volante", "Acelerar para salir del agua"), 1, "Ante el aquaplaning hay que soltar el acelerador suavemente y mantener el volante recto hasta recuperar el contacto con el asfalto."),
            StaticQuestion("¿Cómo afecta el calor extremo a la conducción?", listOf("No afecta al vehículo, solo al conductor", "Puede provocar fatiga en el conductor y afectar a neumáticos y frenos", "Mejora el rendimiento del motor"), 1, "El calor extremo puede causar fatiga, deshidratación del conductor y sobrecalentamiento de neumáticos y frenos."),
            StaticQuestion("¿Qué se recomienda llevar en el vehículo en zonas de nieve en invierno?", listOf("Nada especial", "Cadenas u otros dispositivos antideslizantes homologados", "Solo un rascador de hielo"), 1, "En zonas con posible nieve se recomienda llevar cadenas u otros sistemas antideslizantes homologados.")
        ),

        "node_6_2_lesson" to listOf( // Conducción nocturna
            StaticQuestion("¿Qué luces se usan de noche en carretera bien iluminada?", listOf("Luces largas", "Luces de cruce", "Solo las de posición"), 1, "En vías bien iluminadas se usan las luces de cruce (cortas)."),
            StaticQuestion("¿Cuándo se cambia de luces largas a cruce?", listOf("Nunca", "Al cruzarse con otro vehículo o seguir a uno a corta distancia", "Solo en autopistas"), 1, "Se cambia a cruce para no deslumbrar al vehículo que viene de frente o al que se sigue."),
            StaticQuestion("¿Qué ocurre si le deslumbran?", listOf("Encender las luces largas como respuesta", "Mirar al borde derecho de la calzada y reducir velocidad", "Parar inmediatamente"), 1, "Se mira al borde derecho, se reduce velocidad y se espera a recuperar la visión normal."),
            StaticQuestion("¿Se pueden usar solo las luces de posición para circular?", listOf("Sí, dentro de poblado", "No, las luces de posición nunca son suficientes para circular", "Solo a menos de 30 km/h"), 1, "Para circular es obligatorio como mínimo las luces de cruce; las de posición solo complementan."),
            StaticQuestion("¿De noche se perciben peor los peatones con ropa oscura?", listOf("No, se ven igual", "Sí, son mucho más difíciles de ver", "Solo si no llevan reflectante"), 1, "Los peatones con ropa oscura son muy difíciles de detectar de noche."),
            StaticQuestion("¿Por qué se altera la percepción de distancias y velocidades de noche?", listOf("Por la menor visibilidad y contraste", "No se altera, es igual que de día", "Solo afecta a conductores noveles"), 0, "La menor luminosidad y contraste de noche dificultan calcular correctamente distancias y velocidades."),
            StaticQuestion("¿Es recomendable llevar las lunas y los faros limpios de noche?", listOf("No influye", "Sí, la suciedad dispersa la luz y reduce la visibilidad", "Solo los faros, no las lunas"), 1, "Los faros y lunas sucios dispersan la luz, reducen el alcance de iluminación y favorecen el deslumbramiento."),
            StaticQuestion("¿Qué debe hacer si siente somnolencia conduciendo de noche?", listOf("Abrir la ventanilla y seguir", "Parar y descansar en un lugar seguro", "Poner música más alta"), 1, "Ante la somnolencia lo único eficaz es detenerse en un lugar seguro y descansar."),
            StaticQuestion("¿Aumenta el riesgo de accidente la conducción nocturna?", listOf("No, es igual que de día", "Sí, por la peor visibilidad y la mayor fatiga acumulada", "Solo en carretera, no en ciudad"), 1, "De noche se reduce la visibilidad y aumenta la fatiga, lo que eleva el riesgo de accidente."),
            StaticQuestion("¿Qué luces adicionales pueden usarse con niebla nocturna además de las de cruce?", listOf("Las luces antiniebla", "Las luces largas", "Ninguna otra"), 0, "Con niebla, además de las luces de cruce, se pueden emplear las luces antiniebla delanteras y, si es densa, las traseras.")
        ),

        "node_6_3_lesson" to listOf( // Túneles
            StaticQuestion("¿Qué luces se deben encender al entrar en un túnel?", listOf("Las luces largas", "Las luces de cruce", "Solo las de posición"), 1, "Al entrar en un túnel se encienden las luces de cruce, independientemente de la iluminación."),
            StaticQuestion("¿Se puede adelantar dentro de un túnel?", listOf("Sí, si hay dos carriles por sentido", "No, salvo que haya dos o más carriles por sentido y esté permitido", "Nunca"), 1, "Solo se puede adelantar en túneles con dos o más carriles por sentido y sin prohibición."),
            StaticQuestion("¿Qué debe hacer si su vehículo se avería dentro de un túnel?", listOf("Detenerse y esperar ayuda", "Intentar sacar el vehículo, señalizar, apagar motor y abandonar por las salidas de emergencia", "Llamar al seguro"), 1, "Se debe intentar apartar el vehículo, señalizarlo, apagar el motor y dirigirse a una salida de emergencia."),
            StaticQuestion("¿Se deben quitar las gafas de sol al entrar en un túnel?", listOf("No, no importa", "Sí, la reducción de luminosidad puede impedir ver correctamente", "Solo de noche"), 1, "Se deben quitar las gafas de sol antes de entrar para adaptarse a la iluminación del túnel."),
            StaticQuestion("¿Qué distancia de seguridad conviene en túneles?", listOf("La misma que en carretera", "Mayor, al menos 100 metros o 4 segundos", "No importa"), 1, "En túneles se recomienda aumentar la distancia de seguridad para tener más margen de reacción."),
            StaticQuestion("¿Qué indica un panel con el símbolo de una radio dentro de un túnel?", listOf("Que hay cobertura de radio para escuchar información de tráfico", "Que está prohibido el uso de la radio", "Que hay wifi disponible"), 0, "Muchos túneles indican la frecuencia de radio en la que se emite información de tráfico y emergencias."),
            StaticQuestion("¿Debe respetarse la distancia de seguridad igual dentro de un túnel?", listOf("No, en túneles no aplica", "Sí, e incluso se recomienda aumentarla", "Solo si hay más de un carril"), 1, "La distancia de seguridad debe respetarse en túneles igual o con mayor margen que en el resto de la vía."),
            StaticQuestion("¿Qué debe hacerse si hay un atasco dentro de un túnel?", listOf("Adelantar por el arcén", "Mantener la distancia de seguridad y estar atento a las indicaciones", "Apagar las luces"), 1, "Ante un atasco en túnel hay que mantener distancia con el vehículo de delante y seguir las indicaciones de la señalización."),
            StaticQuestion("¿Está permitido detenerse dentro de un túnel salvo emergencia?", listOf("Sí, en cualquier punto", "No, salvo avería o emergencia, usando apartaderos si existen", "Solo si hay atasco"), 1, "La parada y detención dentro de túneles está prohibida salvo avería o emergencia, utilizando los apartaderos habilitados."),
            StaticQuestion("¿Qué elementos de seguridad suelen tener los túneles largos además de las salidas de emergencia?", listOf("Extintores y postes SOS", "Solo cámaras de tráfico", "Ningún elemento adicional"), 0, "Los túneles largos suelen disponer de extintores, postes SOS y sistemas de ventilación y detección de incendios.")
        ),

        "node_6_4_lesson" to listOf( // Conducción eficiente
            StaticQuestion("¿Cómo se consigue una conducción más eficiente?", listOf("Acelerando rápido y frenando fuerte", "Anticipándose, manteniendo velocidad constante y reduciendo frenazos", "Usando marchas bajas"), 1, "La conducción eficiente se basa en anticipación, suavidad y velocidad estable."),
            StaticQuestion("¿En qué marcha se consume menos combustible?", listOf("En primera, para tener más control", "En la marcha más larga posible sin forzar el motor", "En punto muerto"), 1, "Circular en la marcha más alta posible reduce el consumo de combustible."),
            StaticQuestion("¿El aire acondicionado afecta al consumo?", listOf("No, es insignificante", "Sí, puede aumentar el consumo entre un 5% y un 20%", "Solo en coches viejos"), 1, "El aire acondicionado aumenta significativamente el consumo de combustible."),
            StaticQuestion("¿Es eficiente dejar el motor al ralentí durante paradas largas?", listOf("Sí, gasta poco", "No, es mejor apagar el motor si la parada supera 1-2 minutos", "Solo en diésel"), 1, "En paradas superiores a 1 minuto, es más eficiente apagar el motor (Start-Stop)."),
            StaticQuestion("¿La presión de los neumáticos afecta al consumo?", listOf("No", "Sí, neumáticos desinflados aumentan el consumo", "Solo en carretera"), 1, "Neumáticos con presión baja aumentan la resistencia a la rodadura y el consumo."),
            StaticQuestion("¿El exceso de peso en el vehículo afecta al consumo?", listOf("No", "Sí, a mayor peso, mayor consumo de combustible", "Solo en bajadas"), 1, "Cuanto más peso transporta el vehículo, mayor es el esfuerzo del motor y el consumo de combustible."),
            StaticQuestion("¿Es eficiente frenar bruscamente al final de cada tramo?", listOf("Sí, siempre", "No, es preferible anticipar y dejar rodar el vehículo levantando el acelerador", "No influye en el consumo"), 1, "Anticiparse y dejar rodar el vehículo en lugar de frenar bruscamente reduce el consumo y el desgaste."),
            StaticQuestion("¿Afecta el uso de baca o portabicicletas exterior al consumo?", listOf("No, es insignificante", "Sí, aumenta la resistencia aerodinámica y el consumo", "Solo en ciudad"), 1, "Los accesorios exteriores aumentan la resistencia al aire y elevan el consumo, especialmente a alta velocidad."),
            StaticQuestion("¿Qué papel juega la anticipación en la conducción eficiente?", listOf("Ninguno", "Permite prever el tráfico y evitar frenazos y aceleraciones innecesarias", "Solo sirve para ir más rápido"), 1, "Anticiparse a las situaciones del tráfico evita maniobras bruscas que disparan el consumo."),
            StaticQuestion("¿Es eficiente circular a altas revoluciones de forma constante?", listOf("Sí, siempre", "No, aumenta el consumo y el desgaste del motor", "Solo en motores diésel"), 1, "Mantener revoluciones altas de forma innecesaria incrementa el consumo y el desgaste mecánico.")
        ),

        "node_6_5_lesson" to listOf( // Emisiones, etiquetas DGT y ZBE
            StaticQuestion("¿Cuántas etiquetas ambientales de la DGT existen?", listOf("3", "4: 0 Emisiones, ECO, C y B", "5"), 1, "La DGT otorga 4 etiquetas: 0 Emisiones (azul), ECO (azul-verde), C (verde) y B (amarilla)."),
            StaticQuestion("¿Qué es una ZBE (Zona de Bajas Emisiones)?", listOf("Una zona de aparcamiento", "Un área urbana con restricción de acceso según la etiqueta ambiental", "Una autopista ecológica"), 1, "Las ZBE son áreas urbanas donde se restringe el acceso a vehículos según su nivel de emisiones."),
            StaticQuestion("¿Un vehículo sin etiqueta puede circular en una ZBE?", listOf("Sí, siempre", "Generalmente no, salvo excepciones", "Solo de noche"), 1, "Los vehículos sin etiqueta suelen tener acceso restringido o prohibido en las ZBE."),
            StaticQuestion("¿La etiqueta ambiental es obligatoria?", listOf("Solo en ZBE", "No es obligatoria, pero es necesaria para acceder a ZBE y evitar sanciones", "Sí, siempre"), 1, "No es obligatorio llevarla visible, pero sí necesaria para circular en zonas restringidas."),
            StaticQuestion("¿Qué etiqueta tiene un coche eléctrico puro?", listOf("ECO", "0 Emisiones (azul)", "C (verde)"), 1, "Los vehículos eléctricos puros, de pila de combustible y PHEV de largo alcance reciben la etiqueta 0."),
            StaticQuestion("¿Qué vehículos no reciben ninguna etiqueta ambiental de la DGT?", listOf("Los más antiguos y contaminantes, que no cumplen los requisitos mínimos", "Los eléctricos", "Los híbridos"), 0, "Los vehículos más antiguos o contaminantes que no alcanzan los requisitos de ninguna categoría no reciben distintivo."),
            StaticQuestion("¿Puede variar el nivel de restricción de una ZBE según el día o el episodio de contaminación?", listOf("No, siempre es igual", "Sí, algunos ayuntamientos endurecen las restricciones en episodios de alta contaminación", "Solo depende de la hora del día"), 1, "Muchas ordenanzas de ZBE contemplan restricciones adicionales temporales en episodios de contaminación elevada."),
            StaticQuestion("¿Dónde se puede consultar si un vehículo tiene etiqueta ambiental y cuál le corresponde?", listOf("En la sede electrónica de la DGT", "Solo preguntando en un taller", "No se puede consultar"), 0, "La DGT ofrece un servicio de consulta online del distintivo ambiental por matrícula."),
            StaticQuestion("¿Puede un vehículo híbrido enchufable (PHEV) obtener la etiqueta 0 Emisiones?", listOf("No, nunca", "Sí, si cumple la autonomía mínima en modo eléctrico establecida por la normativa", "Solo si tiene menos de 2 años"), 1, "Los PHEV con autonomía eléctrica suficiente pueden obtener la etiqueta 0, igual que los eléctricos puros."),
            StaticQuestion("¿Afecta la etiqueta ambiental solo al acceso a ZBE o también a otras medidas?", listOf("Solo al acceso a ZBE", "También puede condicionar aparcamiento regulado y restricciones en episodios de contaminación", "No tiene ningún otro uso"), 1, "La etiqueta ambiental se usa además para bonificaciones de aparcamiento y restricciones puntuales por contaminación.")
        ),

        "node_6_6_lesson" to listOf( // Accidentes: conducta PAS
            StaticQuestion("¿Qué significa PAS en primeros auxilios?", listOf("Policía, Ambulancia, Seguridad", "Proteger, Avisar, Socorrer", "Parar, Atender, Salir"), 1, "PAS: Proteger la zona, Avisar a emergencias (112) y Socorrer a los heridos."),
            StaticQuestion("¿Cuál es el número de emergencias en España?", listOf("091", "112", "080"), 1, "El 112 es el teléfono único de emergencias en toda la UE."),
            StaticQuestion("¿Se debe mover a un accidentado?", listOf("Sí, para sacarlo del coche", "No, salvo riesgo inminente (incendio, caída al agua)", "Solo si lo pide"), 1, "No se debe mover al herido a menos que haya peligro inminente (fuego, explosión)."),
            StaticQuestion("¿Se debe quitar el casco a un motorista accidentado?", listOf("Sí, siempre", "No, salvo que no respire y sea imprescindible", "Solo si está consciente"), 1, "El casco no se retira salvo que el herido no respire y sea imprescindible para asistirle."),
            StaticQuestion("¿Es obligatorio auxiliar a las víctimas de un accidente?", listOf("No, solo si se es sanitario", "Sí, la omisión del deber de socorro es delito", "Solo si se ha causado el accidente"), 1, "No auxiliar a las víctimas constituye delito de omisión del deber de socorro."),
            StaticQuestion("¿Qué se debe hacer primero al llegar a un accidente?", listOf("Auxiliar directamente a los heridos sin más", "Proteger el lugar señalizando para evitar más accidentes", "Llamar a un familiar"), 1, "Antes de socorrer hay que proteger la zona para evitar que se produzcan nuevos accidentes."),
            StaticQuestion("¿Es recomendable dar de beber a un herido tras un accidente?", listOf("Sí, siempre", "No, salvo indicación médica, puede ser contraproducente", "Solo si lo pide él mismo"), 1, "No se debe dar de beber ni comer a un accidentado sin indicación médica."),
            StaticQuestion("¿Qué información se debe dar al llamar al 112 tras un accidente?", listOf("Solo el nombre de quien llama", "Lugar exacto, número de heridos y su estado, y tipo de accidente", "No hace falta dar detalles"), 1, "Cuanta más información precisa se aporte al 112, más rápida y adecuada será la respuesta de emergencias."),
            StaticQuestion("¿Se debe apagar el motor de los vehículos implicados en un accidente?", listOf("No es necesario", "Sí, para reducir el riesgo de incendio", "Solo si humea"), 1, "Apagar el motor de los vehículos accidentados reduce el riesgo de incendio."),
            StaticQuestion("¿Qué es la conocida como 'hora dorada' en la atención a heridos graves?", listOf("La primera hora tras el accidente, crucial para la supervivencia", "La hora de mayor tráfico", "Un plazo administrativo para denunciar"), 0, "La 'hora dorada' es el periodo inicial tras un traumatismo grave en el que la atención rápida mejora mucho el pronóstico.")
        ),

        "node_6_7_lesson" to listOf( // Señalización de emergencia
            StaticQuestion("¿Cuántos triángulos de emergencia se llevan actualmente?", listOf("Dos", "Uno, pero se está sustituyendo por la luz V-16", "Ninguno"), 1, "Actualmente se llevan dos triángulos, pero se están sustituyendo por la luz V-16 homologada."),
            StaticQuestion("¿Qué es la luz V-16?", listOf("Una linterna", "Un dispositivo luminoso de preseñalización de peligro homologado", "Una luz de emergencia del vehículo"), 1, "La V-16 es una baliza luminosa geolocalizada que sustituirá a los triángulos."),
            StaticQuestion("¿Es obligatorio llevar chaleco reflectante?", listOf("Solo para conductores profesionales", "Sí, al menos uno por vehículo, y usarlo al salir en vía interurbana", "No, es opcional"), 1, "Es obligatorio llevar un chaleco reflectante y usarlo al salir del vehículo en vía interurbana."),
            StaticQuestion("¿A qué distancia se colocan los triángulos?", listOf("A 10 metros", "A 50 metros como mínimo, uno delante y otro detrás", "A 100 metros detrás"), 1, "Se colocan a al menos 50 metros del vehículo, uno delante y otro detrás (en doble sentido)."),
            StaticQuestion("¿Qué hacer antes de salir del vehículo en una avería en autopista?", listOf("Salir por el lado izquierdo", "Ponerse el chaleco, encender las luces de emergencia y salir por el lado derecho", "Esperar dentro"), 1, "Chaleco reflectante → luces de emergencia → salir por el lado opuesto al tráfico → refugiarse detrás de la barrera."),
            StaticQuestion("¿Sustituye la luz V-16 a los triángulos de emergencia?", listOf("Sí, la normativa avanza hacia su uso generalizado en sustitución de los triángulos", "No, es un complemento sin relación", "Solo para camiones"), 0, "La luz V-16 está sustituyendo progresivamente a los triángulos como dispositivo de preseñalización de peligro."),
