            StaticQuestion("¿Conducir hablando por el móvil sin manos libres es infracción…?", listOf("Leve", "Grave", "Muy grave"), 1, "Usar el móvil sin manos libres al conducir es infracción grave con pérdida de puntos."),
            StaticQuestion("¿Circular sin cinturón de seguridad es infracción…?", listOf("Leve", "Grave", "Muy grave"), 1, "No usar el cinturón de seguridad obligatorio es infracción grave."),
            StaticQuestion("¿No respetar la distancia de seguridad es infracción…?", listOf("Leve", "Grave", "Muy grave"), 1, "No mantener la distancia de seguridad con el vehículo de delante es infracción grave."),
            StaticQuestion("¿Circular con el sistema de retención infantil mal colocado o sin usarlo es infracción…?", listOf("Leve", "Grave", "Muy grave"), 1, "No utilizar correctamente el SRI obligatorio es infracción grave."),
            StaticQuestion("¿Puede considerarse muy grave un exceso de velocidad muy elevado respecto al límite?", listOf("No, siempre es leve", "Sí, según el porcentaje de exceso cometido puede alcanzar la calificación de muy grave", "Nunca es sancionable"), 1, "Cuanto mayor es el porcentaje de exceso sobre el límite, mayor es la gravedad de la infracción, pudiendo llegar a muy grave."),
            StaticQuestion("¿Estacionar de forma que se dificulte gravemente la circulación o cause peligro es infracción…?", listOf("Leve", "Grave", "Muy grave"), 1, "Estacionar dificultando gravemente la circulación u ocasionando peligro se considera infracción grave.")
        ),

        "node_8_1_lesson" to listOf( // Sanciones: multas y retirada
            StaticQuestion("¿Cuál es la multa por exceso de velocidad grave?", listOf("100 euros", "De 300 a 600 euros", "50 euros"), 1, "Las multas por exceso de velocidad grave oscilan entre 300 y 600 euros."),
            StaticQuestion("¿Se puede pagar la multa con descuento?", listOf("No, nunca", "Sí, un 50% de descuento por pronto pago en 20 días naturales", "Solo las leves"), 1, "Se obtiene un 50% de descuento pagando en los 20 días naturales siguientes a la notificación."),
            StaticQuestion("¿Qué implica la retirada del permiso de conducir?", listOf("Solo una penalización económica", "No poder conducir durante el plazo fijado judicialmente", "Un curso de reeducación"), 1, "La retirada judicial prohíbe conducir durante el periodo que fije el juez."),
            StaticQuestion("¿Se puede recurrir una multa de tráfico?", listOf("No, es firme siempre", "Sí, mediante recurso de alzada o reclamación económico-administrativa", "Solo si es grave"), 1, "Toda sanción es recurrible dentro de los plazos legales establecidos."),
            StaticQuestion("¿Una multa de tráfico puede conllevar cárcel?", listOf("No, nunca", "Sí, si la infracción constituye delito contra la seguridad vial", "Solo en caso de accidente"), 1, "Conducir ebrio, a velocidad delictiva o sin permiso pueden ser delitos con pena de prisión."),
            StaticQuestion("¿Qué es la retirada cautelar del vehículo?", listOf("Una sanción puramente económica", "La inmovilización o depósito del vehículo por la autoridad ante determinadas infracciones", "Un tipo de infracción leve"), 1, "Ante determinadas infracciones la autoridad puede inmovilizar o depositar el vehículo cautelarmente."),
            StaticQuestion("¿Puede sancionarse al propietario de un vehículo si no identifica al conductor infractor?", listOf("No, solo se sanciona a quien conducía", "Sí, existe la obligación de identificar al conductor y no hacerlo es sancionable", "Solo si el propietario es una empresa"), 1, "El titular del vehículo tiene el deber de identificar al conductor responsable de la infracción cuando se le requiera."),
            StaticQuestion("¿Prescriben las infracciones de tráfico con el tiempo?", listOf("No, son indefinidas", "Sí, existen plazos de prescripción según su gravedad", "Solo prescriben las leves"), 1, "Las infracciones de tráfico prescriben transcurridos los plazos legales establecidos según su gravedad."),
            StaticQuestion("¿Puede una misma infracción conllevar multa económica y pérdida de puntos a la vez?", listOf("No, son excluyentes", "Sí, muchas infracciones conllevan ambas consecuencias simultáneamente", "Solo en infracciones leves"), 1, "Numerosas infracciones graves y muy graves llevan aparejadas tanto sanción económica como pérdida de puntos."),
            StaticQuestion("¿Qué organismo tramita y resuelve habitualmente las sanciones de tráfico en carreteras estatales?", listOf("La Dirección General de Tráfico (DGT)", "El Ayuntamiento siempre", "Los tribunales civiles"), 0, "La DGT es el organismo competente para tramitar las sanciones de tráfico en vías interurbanas de titularidad estatal.")
        ),

        "node_8_2_lesson" to listOf( // Pérdida y recuperación de puntos
            StaticQuestion("¿Con cuántos puntos empieza un conductor novel?", listOf("12 puntos", "8 puntos", "6 puntos"), 1, "Los conductores noveles comienzan con 8 puntos (suben a 12 tras 2 años sin infracciones)."),
            StaticQuestion("¿Y un conductor con experiencia?", listOf("8 puntos", "12 puntos", "15 puntos"), 1, "Los conductores con más de 2 años de experiencia disponen de 12 puntos."),
            StaticQuestion("¿Se pueden recuperar puntos?", listOf("No, una vez perdidos no se recuperan", "Sí, con cursos de recuperación y por el paso del tiempo sin infracciones", "Solo pagando una tasa"), 1, "Se pueden recuperar hasta 6 puntos con un curso, y todos por buena conducta durante 2-3 años."),
            StaticQuestion("¿Qué ocurre si se pierden todos los puntos?", listOf("Multa y ya está", "Se pierde el permiso de conducir y hay que hacer un curso completo", "Se reducen a la mitad"), 1, "Al llegar a 0 puntos se pierde el permiso y hay que superar un curso y un examen para recuperarlo."),
            StaticQuestion("¿Un conductor bonificado puede llegar a tener más de 12 puntos?", listOf("No, 12 es el máximo", "Sí, hasta 15 puntos por buen comportamiento", "Hasta 20 puntos"), 1, "Los conductores que no cometen infracciones en 3 años pueden alcanzar hasta 15 puntos."),
            StaticQuestion("¿Todas las infracciones de tráfico conllevan pérdida de puntos?", listOf("Sí, todas sin excepción", "No, solo las que la normativa vincula expresamente a pérdida de puntos", "Solo las muy graves"), 1, "Únicamente las infracciones que la normativa asocia expresamente a puntos conllevan su pérdida; no todas la llevan aparejada."),
            StaticQuestion("¿Se puede consultar el saldo de puntos del permiso de conducir?", listOf("No es posible consultarlo", "Sí, a través de la sede electrónica de la DGT", "Solo acudiendo en persona a Jefatura"), 1, "El saldo de puntos puede consultarse online en la sede electrónica de la DGT con certificado o Cl@ve."),
            StaticQuestion("¿Es el mismo curso el de recuperación parcial de puntos que el de sensibilización tras perderlos todos?", listOf("Sí, son idénticos", "No, son cursos distintos en objetivo y duración", "No existen diferencias legales entre ambos"), 1, "El curso de recuperación de puntos y el de sensibilización y reeducación vial son cursos diferentes."),
            StaticQuestion("¿Es único el saldo de puntos para todos los permisos de una misma persona?", listOf("No, cada permiso tiene su propio saldo", "Sí, el saldo de puntos es único, independientemente del número de permisos que se tengan", "Solo si se obtuvieron el mismo año"), 1, "El saldo de puntos está vinculado a la persona titular, no a cada permiso por separado."),
            StaticQuestion("¿Existe algún límite a la frecuencia con la que se puede repetir el curso de recuperación de puntos?", listOf("No, se puede hacer tantas veces como se quiera", "Sí, existe un límite de veces y de periodicidad entre cursos", "Solo se puede hacer una vez en la vida"), 1, "La normativa limita cuántas veces y con qué frecuencia puede repetirse el curso de recuperación de puntos.")
        ),

        "node_8_3_lesson" to listOf( // Seguro obligatorio
            StaticQuestion("¿Es obligatorio tener seguro de responsabilidad civil para circular?", listOf("No, es voluntario", "Sí, es obligatorio para todo vehículo a motor", "Solo en autopistas"), 1, "El seguro de responsabilidad civil (seguro a terceros) es obligatorio por ley."),
            StaticQuestion("¿Qué cubre el seguro a terceros?", listOf("Los daños del propio vehículo", "Los daños causados a terceras personas y sus bienes", "Nada, solo es un trámite"), 1, "El seguro a terceros cubre los daños que causemos a otras personas y sus propiedades."),
            StaticQuestion("¿Qué es un seguro a todo riesgo?", listOf("El más barato", "Cubre daños propios además de los de terceros", "Un seguro ilegal"), 1, "El seguro a todo riesgo incluye la cobertura de daños propios, además de los daños a terceros."),
            StaticQuestion("¿Se puede circular con el seguro vencido?", listOf("Sí, tiene un mes de gracia", "No, circular sin seguro en vigor es infracción muy grave", "Solo dentro de poblado"), 1, "Circular sin seguro vigente es infracción muy grave con multas de 601 a 3.005 euros."),
            StaticQuestion("¿Quién paga si un vehículo sin seguro causa un accidente?", listOf("Nadie", "El conductor responde personalmente y el Consorcio de Compensación de Seguros anticipa los pagos", "La DGT"), 1, "El CCS puede anticipar las indemnizaciones y luego reclamar al responsable."),
            StaticQuestion("¿Qué es el Consorcio de Compensación de Seguros (CCS)?", listOf("Una aseguradora privada más", "Un organismo público que indemniza a las víctimas cuando el vehículo responsable no está asegurado o es desconocido", "Un tipo de sanción administrativa"), 1, "El CCS indemniza a las víctimas de accidentes causados por vehículos sin seguro o no identificados, y luego reclama al responsable."),
            StaticQuestion("¿Es obligatorio llevar siempre encima el documento físico del seguro?", listOf("Sí, siempre en papel", "Es recomendable, aunque la DGT puede verificar su vigencia electrónicamente", "No existe ningún documento de seguro"), 1, "La vigencia del seguro puede comprobarse electrónicamente, aunque es recomendable llevar el justificante."),
            StaticQuestion("¿Qué ocurre en un accidente en el que ambos conductores tienen seguro?", listOf("Nadie se hace cargo de los daños", "Cada aseguradora gestiona la indemnización según la responsabilidad de cada parte", "Paga siempre el que llegó primero al lugar"), 1, "Las aseguradoras implicadas gestionan los daños según el grado de responsabilidad de cada conductor."),
            StaticQuestion("¿Cubre el seguro obligatorio los daños propios del conductor causante del accidente?", listOf("Sí, siempre", "No, el seguro obligatorio solo cubre los daños a terceros", "Solo si el accidente es leve"), 1, "El seguro de responsabilidad civil obligatorio cubre a terceros, no los daños propios del causante."),
            StaticQuestion("¿Se puede circular legalmente sin seguro en vigor aunque sea un trayecto muy corto?", listOf("Sí, si es menos de 1 km", "No, el seguro debe estar en vigor para cualquier desplazamiento por vías públicas", "Solo está exento dentro de una finca privada"), 1, "El seguro obligatorio debe estar en vigor para circular por cualquier vía pública, sin excepción por la distancia recorrida.")
        ),

        "node_8_4_lesson" to listOf( // Responsabilidad civil y penal
            StaticQuestion("¿Qué es la responsabilidad civil del conductor?", listOf("La obligación de cumplir las normas", "La obligación de indemnizar los daños causados a terceros", "La responsabilidad penal"), 1, "La responsabilidad civil obliga a reparar económicamente los daños causados."),
            StaticQuestion("¿Qué es la responsabilidad penal del conductor?", listOf("Pagar las multas", "Responder ante los tribunales por delitos cometidos al volante", "Perder puntos"), 1, "La responsabilidad penal implica un proceso judicial con posibles penas de prisión, multa o privación de derechos."),
            StaticQuestion("¿Conducir sin permiso es delito?", listOf("No, solo infracción administrativa", "Sí, puede ser delito contra la seguridad vial", "Solo si se es reincidente"), 1, "Conducir sin haber obtenido nunca el permiso, o con el permiso retirado, puede ser delito."),
            StaticQuestion("¿Qué es el delito de omisión del deber de socorro?", listOf("No parar en un semáforo", "No ayudar a las víctimas de un accidente pudiendo hacerlo", "No llevar triángulos"), 1, "No auxiliar a las víctimas cuando se puede es delito de omisión del deber de socorro."),
            StaticQuestion("¿Un acompañante puede ser responsable de un accidente?", listOf("Nunca", "Sí, si contribuye a causarlo (ej: distraer al conductor, tirar del volante)", "Solo el conductor es responsable"), 1, "Un acompañante que contribuya al accidente puede ser considerado responsable."),
            StaticQuestion("¿Puede existir responsabilidad civil sin que haya delito penal?", listOf("No, van siempre unidas", "Sí, puede haber obligación de indemnizar sin que el hecho constituya delito", "Solo si hay heridos graves"), 1, "La responsabilidad civil (indemnizar el daño) puede existir de forma independiente a la responsabilidad penal."),
            StaticQuestion("¿Quién suele asumir la indemnización por responsabilidad civil en un accidente de tráfico?", listOf("Siempre el Estado", "Generalmente la compañía aseguradora del vehículo responsable", "Nunca se asume"), 1, "La compañía aseguradora del vehículo causante suele hacerse cargo de la indemnización por responsabilidad civil."),
            StaticQuestion("¿Puede incurrirse en responsabilidad penal sin que haya habido un accidente?", listOf("No, siempre requiere un accidente", "Sí, por ejemplo conducir superando la tasa penal de alcoholemia, aunque no haya accidente", "Solo en caso de reincidencia"), 1, "Determinadas conductas, como superar la tasa penal de alcoholemia, son delito aunque no se produzca un accidente."),
            StaticQuestion("¿Constituye delito la conducción temeraria con manifiesto desprecio por la vida de los demás?", listOf("No, es solo infracción administrativa", "Sí, constituye delito contra la seguridad vial", "Solo si hay más de un testigo presencial"), 1, "La conducción temeraria con manifiesto desprecio por la vida ajena está tipificada como delito."),
            StaticQuestion("¿Puede un menor de edad generar responsabilidad al conducir sin permiso?", listOf("No, los menores no tienen ninguna responsabilidad", "Sí, puede derivar en responsabilidad penal de menores y en sanciones a padres o tutores", "Solo responsabilidad civil de los padres"), 1, "Un menor que conduce sin permiso puede incurrir en responsabilidad penal de menores, además de afectar a sus padres o tutores.")
        ),

        "node_8_5_lesson" to listOf( // Alcoholemia: pruebas y consecuencias
            StaticQuestion("¿Quién puede someterse a una prueba de alcoholemia?", listOf("Solo los sospechosos", "Cualquier conductor puede ser requerido para una prueba", "Solo en caso de accidente"), 1, "Cualquier conductor puede ser requerido por los agentes para someterse a una prueba de alcoholemia."),
            StaticQuestion("¿Qué ocurre si se da positivo en la primera prueba?", listOf("Se retira el permiso inmediatamente", "Se realiza una segunda prueba tras 10 minutos y se puede solicitar análisis de sangre", "Se impone la multa directamente"), 1, "Tras un positivo, se hace una segunda prueba a los 10 minutos; el conductor puede pedir contraste en sangre."),
            StaticQuestion("¿Negarse a la prueba de alcoholemia es…?", listOf("Un derecho del conductor", "Un delito contra la seguridad vial", "Una infracción leve"), 1, "La negativa a someterse a las pruebas de detección es un delito penal."),
            StaticQuestion("¿A partir de qué tasa se considera delito contra la seguridad vial?", listOf("0,5 g/l", "1,2 g/l en sangre (o 0,60 mg/l en aire)", "Cualquier tasa"), 1, "Superar 1,20 g/l en sangre (0,60 mg/l en aire) es delito contra la seguridad vial."),
            StaticQuestion("¿Qué pena puede llevar un delito de alcoholemia?", listOf("Solo multa", "Prisión de 3 a 6 meses o multa, más retirada de permiso", "Solo pérdida de puntos"), 1, "Las penas pueden incluir prisión de 3 a 6 meses o multa, trabajos comunitarios y retirada del permiso."),
            StaticQuestion("¿Puede realizarse un control de alcoholemia sin que haya indicios previos de infracción o accidente?", listOf("No, siempre se necesita un motivo previo", "Sí, los agentes pueden realizar controles preventivos aleatorios", "Solo tras un accidente"), 1, "Los agentes de tráfico pueden someter a cualquier conductor a un control preventivo de alcoholemia, sin necesidad de indicios previos."),
            StaticQuestion("¿Qué diferencia hay entre la tasa administrativa y la tasa penal de alcoholemia?", listOf("No hay diferencia entre ambas", "Superar la tasa administrativa es infracción; superar la tasa penal, más alta, es delito", "La tasa penal es más baja que la administrativa"), 1, "Existen dos umbrales: uno administrativo (infracción) y otro superior que constituye delito contra la seguridad vial."),
            StaticQuestion("¿Puede solicitarse una prueba de contraste tras dar positivo en la prueba de aire espirado?", listOf("No, el resultado del aire es definitivo", "Sí, el conductor tiene derecho a solicitar una prueba de contraste (sangre u orina)", "Solo si lo decide el agente"), 1, "El conductor tiene derecho a solicitar una prueba de contraste sanguínea u otra alternativa tras un resultado positivo."),
            StaticQuestion("¿Afecta la negativa a la prueba de alcoholemia también a los puntos del permiso?", listOf("No, solo constituye delito", "Sí, además de delito conlleva la pérdida de puntos correspondiente", "Solo si hay reincidencia"), 1, "La negativa a las pruebas de detección, además de ser delito, lleva aparejada la pérdida de puntos asociada."),
            StaticQuestion("¿Puede algún medicamento u otro producto influir en el resultado de una prueba de alcoholemia?", listOf("No, es completamente imposible", "Algunos productos con alcohol pueden influir levemente, y conviene informar al agente si se ha tomado alguno", "Sí, siempre anulan la prueba automáticamente"), 1, "Ciertos medicamentos o enjuagues con alcohol pueden influir levemente; es recomendable informar al agente si se han consumido.")
        )
    )

    /**
     * Returns up to [count] questions for the given [nodeId], shuffled.
     */
    fun getQuestionsForNode(nodeId: String, count: Int = 10): List<StaticQuestion> {
        val all = questionsPerNode[nodeId] ?: return emptyList()
        return all.shuffled().take(count)
    }
}
